sysauto_script.script:
var appURL, orgv, auth, api_key;

var grURL = new GlideRecordSecure('sn_sec_int_impl_config');
grURL.addEncodedQuery('configuration=a46f705c83295210b9b19b00feaad3ae^implementation.name=Contrast Application Vulnerability');
grURL.query();
if (grURL.next()) {
    appURL = grURL.value;
}

var grA = new GlideRecordSecure('sn_sec_int_impl_config');
grA.addEncodedQuery('implementation.name=Contrast Application Vulnerability^configuration=13ff309c83295210b9b19b00feaad319');
grA.query();
if (grA.next()) {
    orgv = grA.value;

}
var gri = new GlideRecordSecure('sn_sec_int_impl_config');
gri.addEncodedQuery('implementation.name=Contrast Application Vulnerability^configuration=6fbf705c83295210b9b19b00feaad30e');
gri.query();

var grk = new GlideRecordSecure('sn_sec_int_impl_config');
grk.addEncodedQuery('implementation.name=Contrast Application Vulnerability^configuration=3a1f705c83295210b9b19b00feaad360');
grk.query();
if (gri.next() && grk.next()) {
    auth = gri.value;
    api_key = grk.value;
}



var gr1 = new GlideRecord('x_ntsi_contrast_ap_contrast_vulnerability_status_sync');
//gr1.addEncodedQuery("sys_created_onONLast 15 minutes@javascript:gs.beginningOfLast15Minutes()@javascript:gs.endOfLast15Minutes()^type=IAST");
gr1.addEncodedQuery('type=IAST');
gr1.addEncodedQuery('response=NULL');
gr1.orderBy('sys_created_on');
gr1.query();
while (gr1.next()) {
    runIntegration(appURL, orgv, auth, api_key);
}

function runIntegration(appURL, orgv, auth, api_key) {

    //Trigger API
    try {
        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'IAST OUTBOUND');
        r.setEndpoint("https://" + appURL + "/Contrast/api/ng/" + orgv + "/orgtraces/mark");
        r.setRequestHeader('API-Key', api_key);
        r.setRequestHeader('Authorization', auth);
        r.setRequestHeader('Content-Type', 'application/json');
        r.setRequestBody(gr1.payload.toString());
        var response = r.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        gr1.response = httpStatus + ' - ' + responseBody;
        gr1.update();
    } catch (ex) {
        var message = ex.message;
    }
}
